// Set these values before activating this workflow.
const sourceKey = 'your_organisation';
const collection = 'openbesluitvorming';
const checkpointId = '00000000-0000-5000-8000-000000000001';
return [{ json: { runId: `openbesluitvorming-page-${Date.now()}`, sourceKey, collection, checkpointId, qdrantBase: 'http://qdrant:6333', vectorSize: 3072, snapshotLimit: 20 } }];

const cfg = $('2. Configure Ingest').first().json;
const response = $input.first().json || {};
const error = response.error || null;
const status = Number(response.statusCode || response.status || error?.httpCode || error?.statusCode || 0);
const body = response.body || response.data || response;
const text = typeof body === 'string' ? body : JSON.stringify(body);
if (status === 404 || text.includes('Not found: Collection')) return [{ json: { ...cfg, collectionAction: 'create' } }];
if (error || (status && (status < 200 || status >= 300))) throw new Error(`Qdrant collection check failed: HTTP ${status || 'unknown'}`);
const vectors = body.result?.config?.params?.vectors;
if (!vectors || Number(vectors.size) !== cfg.vectorSize || vectors.distance !== 'Cosine') throw new Error('Qdrant collection schema mismatch');
return [{ json: { ...cfg, collectionAction: 'ready' } }];

const cfg = $('7. Prepare Checkpoint Lookup').first().json;
const response = $input.first().json || {};
const payload = response.result?.payload || response.payload || null;
if (response.error || !payload || payload.kind !== 'ori_checkpoint' || payload.source_key !== cfg.sourceKey) return [{ json: { ...cfg, cursor: null, pages: 0, indexed: 0, failed: 0, truncated: 0, dead_letters: [], changes_cursor: null, completed: false } }];
return [{ json: { ...cfg, cursor: payload.cursor || null, pages: Number(payload.pages || 0), indexed: Number(payload.indexed || 0), failed: Number(payload.failed || 0), truncated: Number(payload.truncated || 0), dead_letters: payload.dead_letters || [], changes_cursor: payload.changes_cursor || null, completed: payload.completed === true } }];

const cfg = $('9. Resume From Durable Checkpoint').first().json;
const response = $input.first().json || {};
const headers = response.headers || {};
const body = String(response.body || response.data || '');
const documents = body.split('\n').filter(Boolean).map(line => { try { return JSON.parse(line); } catch { return null; } }).filter(record => record?.op === 'upsert' && record.entity_type === 'Document');
return [{ json: { ...cfg, documents, maxDocumentsInPage: documents.length, nextCursor: headers['x-next-cursor'] || null, hasMore: headers['x-has-more'] === 'true' || headers['x-has-more'] === true, changesCursor: cfg.changes_cursor || headers['x-changes-cursor'] || null, page: cfg.pages + 1 } }];

const page = $('12. Parse Page And Next Cursor').first().json;
const summary = $input.first().json.pageSummary || { indexed: 0, failed: 1, truncated: 0, outcomes: [{ outcome: 'dead_letter', stage: 'worker', code: 'invalid_worker_summary', message: 'Worker returned no page summary' }] };
return [{ json: { page, summary } }];

const data = $input.first().json;
const page = data.page, summary = data.summary;
const prior = $('9. Resume From Durable Checkpoint').first().json;
const deadLetters = summary.outcomes.filter(item => item.outcome === 'dead_letter').map(item => ({ entity_id: item.entityId, stage: item.stage || null, code: item.code || null, message: item.message || null, recorded_at: new Date().toISOString() }));
const checkpoint = { kind: 'ori_checkpoint', source_key: page.sourceKey, cursor: page.nextCursor, completed: !page.hasMore || !page.nextCursor, pages: page.page, indexed: Number(prior.indexed || 0) + Number(summary.indexed || 0), failed: Number(prior.failed || 0) + Number(summary.failed || 0), truncated: Number(prior.truncated || 0) + Number(summary.truncated || 0), dead_letters: [...(prior.dead_letters || []), ...deadLetters].slice(-2000), changes_cursor: prior.changes_cursor || page.changesCursor || null, last_page_at: new Date().toISOString(), last_page_documents: page.maxDocumentsInPage };
const zeroVector = new Array(page.vectorSize).fill(0);
return [{ json: { ...page, checkpoint, checkpointPoint: { id: page.checkpointId, vector: zeroVector, payload: checkpoint } } }];

const page = $('16. Build Durable Checkpoint').first().json;
console.log(JSON.stringify({ run_id: page.runId, event: 'page_committed', source_key: page.sourceKey, page: page.checkpoint.pages, page_documents: page.checkpoint.last_page_documents, total_indexed: page.checkpoint.indexed, total_failed: page.checkpoint.failed, next_cursor: page.checkpoint.cursor, completed: page.checkpoint.completed }));
return [{ json: { status: page.checkpoint.completed ? 'completed' : 'page_committed', source_key: page.sourceKey, page: page.checkpoint.pages, page_documents: page.checkpoint.last_page_documents, indexed: page.checkpoint.indexed, failed: page.checkpoint.failed, truncated: page.checkpoint.truncated, next_cursor: page.checkpoint.cursor, completed: page.checkpoint.completed, changes_cursor: page.checkpoint.changes_cursor } }];

const page = $('12. Parse Page And Next Cursor').first().json;
const prior = $('9. Resume From Durable Checkpoint').first().json;
const checkpoint = { kind: 'ori_checkpoint', source_key: page.sourceKey, cursor: page.nextCursor, completed: !page.hasMore || !page.nextCursor, pages: page.page, indexed: Number(prior.indexed || 0), failed: Number(prior.failed || 0), truncated: Number(prior.truncated || 0), dead_letters: prior.dead_letters || [], changes_cursor: prior.changes_cursor || page.changesCursor || null, last_page_at: new Date().toISOString(), last_page_documents: 0 };
return [{ json: { ...page, checkpoint, checkpointPoint: { id: page.checkpointId, vector: new Array(page.vectorSize).fill(0), payload: checkpoint } } }];
